import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int n = Integer.parseInt(st.nextToken());
        ArrayDeque<String> stack = new ArrayDeque<>();
        HashSet<String> held = new HashSet<>();
        for (int i = 1; i <= n; i++) {
            String op = st.nextToken(), name = st.nextToken();
            if (op.equals("ACQUIRE")) {
                if (!held.add(name)) { System.out.println(i); return; }
                stack.push(name);
            } else {
                // Release must match the most recent unreleased acquire.
                if (stack.isEmpty() || !stack.peek().equals(name)) { System.out.println(i); return; }
                stack.pop();
                held.remove(name);
            }
        }
        System.out.println(stack.isEmpty() ? 0 : n + 1);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() string { sc.Scan(); return sc.Text() }
	n, _ := strconv.Atoi(next())
	var stack []string
	held := map[string]bool{}
	for i := 1; i <= n; i++ {
		op, name := next(), next()
		if op == "ACQUIRE" {
			if held[name] {
				fmt.Println(i)
				return
			}
			held[name] = true
			stack = append(stack, name)
		} else {
			// Release must match the most recent unreleased acquire.
			if len(stack) == 0 || stack[len(stack)-1] != name {
				fmt.Println(i)
				return
			}
			stack = stack[:len(stack)-1]
			delete(held, name)
		}
	}
	if len(stack) == 0 {
		fmt.Println(0)
	} else {
		fmt.Println(n + 1)
	}
}
